 IF actual IS DISTINCT FROM expected.shape THEN RAISE EXCEPTION 'Delivery function drift: %',expected.signature;END IF;
 END LOOP;
 SELECT pg_get_triggerdef(t.oid,false) INTO actual FROM pg_trigger t WHERE t.tgrelid='forge_agent.post_merge_verifications'::regclass AND t.tgname='delivery_post_merge_sync' AND t.tgenabled='O' AND NOT t.tgisinternal;
 IF actual IS DISTINCT FROM 'CREATE TRIGGER delivery_post_merge_sync AFTER INSERT OR UPDATE ON forge_agent.post_merge_verifications FOR EACH ROW EXECUTE FUNCTION forge_agent.delivery_sync_post_merge()' THEN RAISE EXCEPTION 'Delivery source signal drift';END IF;
